package com.nook.widgets;

import android.app.*;
import android.appwidget.*;
import android.content.*;
import android.graphics.Bitmap;
import android.net.Uri;
import android.view.View;
import android.widget.RemoteViews;
import org.json.*;
import java.util.*;

/** Video-first widget with inline transport, icon controls and a per-copy carousel. */
public final class VideoWidgets {
    private VideoWidgets(){}
    public static double aspect(JSONObject config,JSONObject info){return switch(config.optInt("videoShape",0)){case 1->16/9d;case 2->1d;case 3->9/16d;default->Math.max(.2,Math.min(5,info.optInt("width",16)/(double)Math.max(1,info.optInt("height",9))));};}
    public static int[] preferred(Context c,JSONObject config){JSONObject info=MediaData.cached(c,config);double ratio=aspect(config,info);if(ratio<.8)return new int[]{180,320};if(ratio>1.25)return new int[]{320,200};return new int[]{260,260};}
    public static Class<?> provider(Context c,JSONObject config){double ratio=aspect(config,MediaData.cached(c,config));return ratio<.8?Widgets.VideoPortrait.class:ratio>1.25?Widgets.Video.class:Widgets.VideoSquare.class;}
    private static PendingIntent transport(Context c,int id,String op,boolean mutable){return PendingIntent.getBroadcast(c,0,new Intent(c,WidgetActionReceiver.class).setAction("motion_action").putExtra("widget",id).putExtra("op",op).setData(Uri.parse("nook://video-transport/"+id+"/"+op)),PendingIntent.FLAG_UPDATE_CURRENT|(mutable?PendingIntent.FLAG_MUTABLE:PendingIntent.FLAG_IMMUTABLE));}
    public static RemoteViews render(Context c,int id,JSONObject config,boolean small,boolean preview){
        JSONObject current=MediaData.active(config),info=MediaData.cached(c,current);List<String> videos=MediaData.videos(config);boolean configured=!videos.isEmpty(),poster=config.optInt("variant",0)==1;
        JSONObject state=id>0&&!preview?InlineVideoState.state(c,id,current,info):new JSONObject();boolean playing=configured&&!poster&&state.optBoolean("playing",!config.optBoolean("videoPaused",false));int pace=WidgetDesign.clamp(config.optInt("videoPace",1),0,2);
        boolean live=playing&&id>0&&!preview;int layout=WidgetDesign.layout(c,live?new String[]{"widget_video_live_slow","widget_video_live","widget_video_live_fast"}[pace]:config.optBoolean("videoCrop",false)?"widget_video_still_crop":"widget_video_still",config);
        RemoteViews view=new RemoteViews(c.getPackageName(),layout);WidgetDesign.Colors colors=WidgetDesign.colors(config,"video");view.setImageViewResource(R.id.widget_surface,Widgets.surfaceResource(config,"video"));for(int n=0;n<3;n++)view.setImageViewResource(Widgets.BACKGROUND_IMAGES[n+1],Widgets.chipResource(config,"video"));for(int bg:Widgets.BACKGROUND_IMAGES)view.setInt(bg,"setImageAlpha",Widgets.surfaceAlpha(config));
        WidgetDesign.surfaces(c,view,id,"video",config,small,new int[]{R.id.widget_action_bg0,R.id.widget_action_bg1,R.id.widget_action_bg2});view.setViewVisibility(R.id.widget_surface,config.optBoolean("videoBackground",false)?View.VISIBLE:View.GONE);
        boolean noText=config.optBoolean("videoHideText",false);view.setViewVisibility(R.id.video_text,noText?View.GONE:View.VISIBLE);view.setViewVisibility(R.id.widget_label,config.optBoolean("showLabel",true)?View.VISIBLE:View.GONE);view.setTextViewTextSize(R.id.widget_title,android.util.TypedValue.COMPLEX_UNIT_SP,14*WidgetDesign.scale(config));view.setTextViewTextSize(R.id.widget_meta,android.util.TypedValue.COMPLEX_UNIT_SP,10*WidgetDesign.scale(config));view.setTextViewText(R.id.widget_title,configured?info.optString("name",current.optString("videoName","Your video")):"Choose videos in Options");view.setTextViewText(R.id.widget_label,config.optString("title","").isEmpty()?"Video carousel":config.optString("title"));view.setTextViewText(R.id.widget_meta,configured?(MediaData.videoIndex(config)+1)+" / "+videos.size()+" · "+(poster?"Still":playing?"Silent inline playback":"Paused"):"Choose one or more videos");for(int text:new int[]{R.id.widget_title,R.id.widget_label,R.id.widget_meta})view.setTextColor(text,colors.text);
        int[] buttons={R.id.widget_action0,R.id.widget_action1,R.id.widget_action2,R.id.widget_settings};int[] icons={R.drawable.ic_video_previous,playing?R.drawable.ic_video_pause:R.drawable.ic_video_play,R.drawable.ic_video_next,R.drawable.ic_video_options};String[] descriptions={"Previous video",playing?"Pause inline video":"Play inline video","Next video","Video options"};for(int n=0;n<buttons.length;n++){view.setImageViewResource(buttons[n],icons[n]);view.setInt(buttons[n],"setColorFilter",colors.text);view.setContentDescription(buttons[n],descriptions[n]);}
        int[] size=WidgetDesign.size(c,id,"video",config,small);double source=info.optInt("width",16)/(double)Math.max(1,info.optInt("height",9));int x=0,y=0;if(!config.optBoolean("videoCrop",false)){if(size[0]/(double)size[1]>source)x=Math.max(0,(int)((size[0]-size[1]*source)/2));else y=Math.max(0,(int)((size[1]-size[0]/source)/2));}view.setViewPadding(R.id.video_overlay,Ui.dp(c,x+6),Ui.dp(c,y+6),Ui.dp(c,x+6),Ui.dp(c,y+6));
        if(live){String session=state.optString("session");String appearance=(config.optBoolean("videoCrop",false)?"crop":"fit")+"/"+pace;Intent service=new Intent(c,InlineVideoService.class).putExtra("widget",id).putExtra("session",session).putExtra("offset",InlineVideoState.position(c,state,InlineVideoState.duration(current,info))).putExtra("config",current.toString()).setData(Uri.parse("nook://video-frames/"+id+"/"+session+"/"+appearance));view.setRemoteAdapter(R.id.video_flipper,service);view.setPendingIntentTemplate(R.id.video_flipper,transport(c,id,"video_toggle",true));}
        else{Bitmap image=id>0&&!poster?MediaData.pausedFrame(c,id,current):null;if(image==null)image=MediaData.frame(c,current,info,0);if(image!=null){view.setImageViewBitmap(R.id.video_poster,MediaData.videoFrame(c,image,1));image.recycle();}else view.setImageViewResource(R.id.video_poster,R.drawable.ic_video_play);view.setViewVisibility(R.id.video_poster,View.VISIBLE);}
        view.setContentDescription(R.id.widget_root,configured?"Video "+(MediaData.videoIndex(config)+1)+" of "+videos.size()+". "+(playing?"Playing silently inside the widget":"Paused"):"Choose videos in widget options");
        if(!preview){PendingIntent setup=LibraryWidgets.configure(c,id,"video");view.setOnClickPendingIntent(R.id.widget_settings,setup);view.setOnClickPendingIntent(R.id.widget_action0,configured?transport(c,id,"video_previous",false):setup);view.setOnClickPendingIntent(R.id.widget_action1,configured?transport(c,id,"video_toggle",false):setup);view.setOnClickPendingIntent(R.id.widget_action2,configured?transport(c,id,"video_next",false):setup);if(!live)view.setOnClickPendingIntent(R.id.video_poster,configured?transport(c,id,"video_toggle",false):setup);}
        return view;
    }
    public static void receive(Context c,int id,String op){AppWidgetProviderInfo info=AppWidgetManager.getInstance(c).getAppWidgetInfo(id);if(info==null)return;String provider=Widgets.kindOf(info.provider);JSONObject root=Store.config(c,id);String kind=provider.equals("universal")?UniversalWidget.currentPage(root):provider;if(!kind.equals("video"))return;JSONObject settings=provider.equals("universal")?UniversalWidget.pageSettings(root,"video"):root;List<String> videos=MediaData.videos(settings);if(videos.isEmpty())return;JSONObject current=MediaData.active(settings),cache=MediaData.cached(c,current),state=InlineVideoState.state(c,id,current,cache);
        if("video_toggle".equals(op)){if(settings.optInt("variant",0)==1){ExtraData.put(settings,"variant",0);ExtraData.put(settings,"videoPaused",false);InlineVideoState.reset(c,id);}else{if(state.optBoolean("playing",true)){Bitmap frame=InlineVideoService.snapshot(id);if(frame!=null){MediaData.pauseFrame(c,id,current,frame);frame.recycle();}InlineVideoService.forget(id);}InlineVideoState.toggle(c,id,MediaData.active(settings),cache);ExtraData.put(settings,"videoPaused",!InlineVideoState.state(c,id,current,cache).optBoolean("playing",true));}}else if("video_previous".equals(op)||"video_next".equals(op)){ExtraData.put(settings,"videoPaused",!state.optBoolean("playing",true));ExtraData.put(settings,"videoIndex",Math.floorMod(MediaData.videoIndex(settings)+(op.endsWith("next")?1:-1),videos.size()));InlineVideoState.reset(c,id);}else return;Store.config(c,id,root);Widgets.update(c,id,provider);
    }
}
